import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Dashboard = ({ token, setToken, setStats, addNotification }) => {
  const [ledgerData, setLedgerData] = useState({
    date: new Date().toISOString().split('T')[0],
    description: '',
    amount: '',
    category: 'expense'
  });
  const [entries, setEntries] = useState([]);
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [uploadFile, setUploadFile] = useState(null);
  const [localStats, setLocalStats] = useState({ total: 0, anomalies: 0, normal: 0 });
  const [currentPage, setCurrentPage] = useState(1);
  const entriesPerPage = 10;

  const fetchEntries = async () => {
    if (!token) return;

    try {
      const response = await axios.get('http://localhost:5000/api/ledger', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setEntries(response.data.entries);

      const total = response.data.total_count;
      const anomalies = response.data.anomaly_count;
      const normal = total - anomalies;
      const statsData = { total, anomalies, normal };
      setLocalStats(statsData);
      if (setStats) setStats(statsData);
    } catch (error) {
      console.error('Failed to fetch entries:', error);
      if (error.response?.status === 401) {
        setToken(null);
      }
    }
  };

  useEffect(() => {
    if (token) {
      fetchEntries();
    }
  }, [token]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    try {
      const response = await axios.post('http://localhost:5000/api/ledger', ledgerData, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.is_anomaly) {
        const alertMessage = `🚨 ANOMALY DETECTED! Entry ID ${response.data.entry_id} - Amount: ₹${parseFloat(ledgerData.amount).toLocaleString('en-IN')}`;
        setMessage({
          type: 'anomaly',
          text: `${alertMessage}. Authority has been notified via email.`
        });
        // Add to header notifications
        if (addNotification) {
          addNotification(alertMessage, 'anomaly');
        }
      } else {
        setMessage({
          type: 'success',
          text: `✅ Transaction recorded successfully with ID ${response.data.entry_id}`
        });
        if (addNotification) {
          addNotification(`✅ New transaction added - ₹${parseFloat(ledgerData.amount).toLocaleString('en-IN')}`, 'success');
        }
      }

      // Reset form
      setLedgerData({
        date: new Date().toISOString().split('T')[0],
        description: '',
        amount: '',
        category: 'expense'
      });

      // Refresh entries
      fetchEntries();
    } catch (error) {
      setMessage({
        type: 'error',
        text: error.response?.data?.error || 'Submission failed'
      });
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = async (e) => {
    e.preventDefault();
    if (!uploadFile) {
      setMessage({ type: 'error', text: 'Please select a file' });
      return;
    }

    setLoading(true);
    setMessage('');

    const formData = new FormData();
    formData.append('file', uploadFile);

    try {
      const response = await axios.post('http://localhost:5000/api/upload-csv', formData, {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'multipart/form-data'
        }
      });

      if (response.data.anomaly_count > 0) {
        const alertMessage = `🚨 ${response.data.anomaly_count} anomalies detected in bulk upload!`;
        setMessage({
          type: 'anomaly',
          text: `File processed! ${response.data.anomaly_count} anomalies detected out of ${response.data.added_count} entries. Authorities notified.`
        });
        if (addNotification) {
          addNotification(alertMessage, 'anomaly');
        }
      } else {
        setMessage({
          type: 'success',
          text: `File processed successfully! ${response.data.added_count} entries added, no anomalies detected.`
        });
        if (addNotification) {
          addNotification(`📁 Bulk upload completed - ${response.data.added_count} entries`, 'success');
        }
      }

      setUploadFile(null);
      document.getElementById('fileInput').value = '';
      fetchEntries();
    } catch (error) {
      setMessage({
        type: 'error',
        text: error.response?.data?.error || 'Upload failed'
      });
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e) => {
    setLedgerData({
      ...ledgerData,
      [e.target.name]: e.target.value
    });
  };

  return (
    <div className="page-content">
      {/* Message Display */}
      {message && (
        <div className={message.type === 'anomaly' ? 'anomaly-alert' : 
                       message.type === 'success' ? 'success-message' : 'error'}>
          {message.text}
        </div>
      )}

      {/* Security Overview Cards */}
      <div className="stats-grid">
        <div className="stat-card">
          <div className="stat-icon">🛡️</div>
          <div className="stat-content">
            <h3>Security Status</h3>
            <div className="stat-number" style={{color: localStats.anomalies > 0 ? '#dc2626' : '#059669'}}>
              {localStats.anomalies > 0 ? 'ALERT' : 'SECURE'}
            </div>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon">📊</div>
          <div className="stat-content">
            <h3>Total Transactions</h3>
            <div className="stat-number">{localStats.total}</div>
          </div>
        </div>

        <div className="stat-card anomaly">
          <div className="stat-icon">⚠️</div>
          <div className="stat-content">
            <h3>Security Alerts</h3>
            <div className="stat-number">{localStats.anomalies}</div>
          </div>
        </div>

        <div className="stat-card success">
          <div className="stat-icon">✅</div>
          <div className="stat-content">
            <h3>Verified Safe</h3>
            <div className="stat-number">{localStats.normal}</div>
          </div>
        </div>
      </div>

      {/* File Upload Card */}
      <div className="card">
        <div className="card-header">
          <h2>📁 Bulk Transaction Upload</h2>
        </div>
        <div className="card-body">
          <form onSubmit={handleFileUpload}>
            <div className="form-group">
              <label>Select CSV File</label>
              <input
                id="fileInput"
                type="file"
                accept=".csv"
                onChange={(e) => setUploadFile(e.target.files[0])}
                required
                className="form-input"
              />
            </div>
            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? 'Processing...' : 'Upload & Analyze'}
            </button>
          </form>
          <div className="help-text">
            <strong>Required columns:</strong> date, description, amount, category
          </div>
        </div>
      </div>

      {/* Manual Entry Card */}
      <div className="card">
        <div className="card-header">
          <h2>✏️ Manual Transaction Entry</h2>
        </div>
        <div className="card-body">
          <form onSubmit={handleSubmit}>
            <div className="form-grid">
              <div className="form-group">
                <label>Date</label>
                <input
                  type="date"
                  name="date"
                  value={ledgerData.date}
                  onChange={handleChange}
                  required
                  className="form-input"
                />
              </div>
              <div className="form-group">
                <label>Category</label>
                <select
                  name="category"
                  value={ledgerData.category}
                  onChange={handleChange}
                  required
                  className="form-select"
                >
                  <option value="expense">💸 Expense</option>
                  <option value="income">💰 Income</option>
                  <option value="transfer">🔄 Transfer</option>
                  <option value="investment">📈 Investment</option>
                  <option value="loan">🏦 Loan</option>
                  <option value="other">📋 Other</option>
                </select>
              </div>
              <div className="form-group">
                <label>Amount (₹)</label>
                <input
                  type="number"
                  step="0.01"
                  name="amount"
                  value={ledgerData.amount}
                  onChange={handleChange}
                  required
                  placeholder="Enter amount in rupees"
                  className="form-input"
                />
              </div>
            </div>
            <div className="form-group">
              <label>Description</label>
              <textarea
                name="description"
                value={ledgerData.description}
                onChange={handleChange}
                required
                placeholder="Enter detailed transaction description..."
                className="form-textarea"
                rows="3"
              />
            </div>
            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? 'Processing...' : 'Submit Transaction'}
            </button>
          </form>
        </div>
      </div>

      {/* Entries Table Card */}
      <div className="card">
        <div className="card-header">
          <h2>🔍 Transaction Monitor</h2>
          <div className="card-actions">
            <button onClick={exportPDF} className="btn btn-secondary">
              📄 Export PDF
            </button>
          </div>
        </div>

        <div className="card-body">
          {entries.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '3rem', color: '#718096' }}>
              <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>🛡️</div>
              <p>No transactions found. Start by adding your first transaction!</p>
            </div>
          ) : (
            <>
              <div className="table-container">
                <table className="entries-table">
                  <thead>
                    <tr>
                      <th style={{width: '100px'}}>Date</th>
                      <th style={{minWidth: '200px'}}>Description</th>
                      <th style={{width: '120px'}}>Amount</th>
                      <th style={{width: '100px'}}>Category</th>
                      <th style={{width: '100px'}}>Security Status</th>
                      <th style={{width: '140px'}}>Recorded</th>
                    </tr>
                  </thead>
                  <tbody>
                    {(() => {
                      const startIndex = (currentPage - 1) * entriesPerPage;
                      const endIndex = startIndex + entriesPerPage;
                      return entries.slice(startIndex, endIndex);
                    })().map((entry) => (
                      <tr key={entry.id} className={entry.is_anomaly ? 'anomaly-row' : ''}>
                        <td>{entry.date}</td>
                        <td>{entry.description}</td>
                        <td>₹{parseFloat(entry.amount).toLocaleString('en-IN', {minimumFractionDigits: 2})}</td>
                        <td style={{ textTransform: 'capitalize' }}>
                          {entry.category === 'expense' && '💸'} 
                          {entry.category === 'income' && '💰'} 
                          {entry.category === 'transfer' && '🔄'} 
                          {entry.category === 'investment' && '📈'} 
                          {entry.category === 'loan' && '🏦'} 
                          {entry.category === 'other' && '📋'} 
                          {entry.category}
                        </td>
                        <td>
                          {entry.is_anomaly ? (
                            <span className="anomaly-badge">🚨 ALERT</span>
                          ) : (
                            <span className="normal-badge">✅ SAFE</span>
                          )}
                        </td>
                        <td>{new Date(entry.created_at).toLocaleString('en-IN', {
                          year: 'numeric',
                          month: '2-digit',
                          day: '2-digit',
                          hour: '2-digit',
                          minute: '2-digit',
                          hour12: true
                        })}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {/* Navigation Controls - Always show when there are entries */}
              {entries.length > entriesPerPage && (
                <div className="pagination">
                  <div className="pagination-info">
                    Showing {((currentPage - 1) * entriesPerPage) + 1} to {Math.min(currentPage * entriesPerPage, entries.length)} of {entries.length} transactions
                  </div>
                  <div className="pagination-controls">
                    <button 
                      onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                      disabled={currentPage === 1}
                      className="pagination-btn"
                    >
                      ← Previous
                    </button>
                    <span className="page-info">
                      Page {currentPage} of {Math.ceil(entries.length / entriesPerPage)}
                    </span>
                    <button 
                      onClick={() => setCurrentPage(prev => Math.min(prev + 1, Math.ceil(entries.length / entriesPerPage)))}
                      disabled={currentPage >= Math.ceil(entries.length / entriesPerPage)}
                      className="pagination-btn"
                    >
                      Next →
                    </button>
                  </div>
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
